const b = ($input.first() && $input.first().json && $input.first().json.body) || {};
const wo = (b.workout || 'Peito').toString();
const streak = Number(b.streak) || 0;
const S = {
  Costas: 'Costas e biceps puxam: hoje constroi o clinch e o controlo. No saco, gancho de retorno ao sair do agarrao.',
  Peito: 'Peito e ombro empurram: e o teu direto e cruzado. Hoje, 1-2 seco e reto, sem telegrafar.',
  Pernas: 'A forca do soco nasce do chao. Pernas hoje = base e explosao. Trabalha footwork e entradas.',
  Potencia: 'Dia de potencia: quadril e cadeia posterior, o que da o nocaute. No saco, cruzado pesado com giro total.',
  Recup: 'Recuperacao: hoje a luta e tecnica. Sombra limpa, guarda perfeita, retorno rapido.'
};
let msg = S[wo] || ('Treino de hoje: ' + wo + '. Tudo o que fazes no ginasio vira soco, guarda ou base. Leva a serio.');
if (streak >= 5) msg += ' ' + streak + ' dias seguidos — e disto que se faz um lutador.';
return [{ json: { coach: 'ILIA', flag: 'FOCO', msg, workout: wo } }];
